public int findLargestSubstring(List<String> strings) {
    // Step 1: Check if there are any non-empty strings in the input list
    if (strings.stream().noneMatch(s -> !s.isEmpty())) {
        return 0;
    }

    // Step 2: Find the longest string in the input list
    String longestString = strings.stream().max(Comparator.comparing(String::length)).get();

    // Step 3: Find the largest substring of the longest string that can be found in any of the other strings
    int longestMatchingSubstring = 0;
    for (String string : strings) {
        if (string.equals(longestString)) {
            continue;
        }
        for (int i = 0; i < string.length(); i++) {
            for (int j = i + 1; j <= string.length(); j++) {
                String substring = string.substring(i, j);
                if (longestString.contains(substring) || longestString.startsWith(substring) || longestString.endsWith(substring)) {
                    longestMatchingSubstring = Math.max(longestMatchingSubstring, substring.length());
                }
            }
        }
    }

    return longestMatchingSubstring;
}

