public int findLargestSubstring(List<String> strings) {
    // Sort the strings by their lengths in descending order
    List<String> sortedStrings = strings.stream().sorted((s1, s2) -> s2.length() - s1.length()).collect(Collectors.toList());

    // Check if any of the strings is a substring of another string
    for (int i = 0; i < sortedStrings.size(); i++) {
        String str1 = sortedStrings.get(i);
        for (int j = i + 1; j < sortedStrings.size(); j++) {
            String str2 = sortedStrings.get(j);
            if (str1.contains(str2) || str2.contains(str1)) {
                return Math.max(str1.length(), str2.length());
            }
        }
    }

    // If no substring is found, return 0
    return 0;
}

