public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

   // Initialize a boolean array to keep track of visited n-tersections
   boolean[] visited = new boolean[n];

   // Mark the starting n-tersection as visited
   visited[start[0] * n + start[1]] = true;

   // Create a queue to hold the n-tersections to be visited
   Queue<Integer> queue = new LinkedList<Integer>();
   queue.offer(start[0] * n + start[1]);

   // Loop until the queue is empty
   while (!queue.isEmpty()) {

       // Get the current n-tersection from the queue
       int current = queue.poll();

       // Check if the current n-tersection is the ending n-tersection
       if (current == end[0] * n + end[1]) {
           return "can be travelled";
       }

       // Get the neighbors of the current n-tersection
       int[] neighbors = getNeighbors(current, paths);

       // Loop through the neighbors
       for (int neighbor : neighbors) {

           // Check if the neighbor has been visited
           if (!visited[neighbor]) {

               // Mark the neighbor as visited
               visited[neighbor] = true;

               // Add the neighbor to the queue
               queue.offer(neighbor);
           }
       }
   }

   return "cannot be travelled";
}

