    // Create a map to count the number of common letters
    Map<Character, Integer> commonLetters = new HashMap<>();
    for (int i = 0; i < word1.length(); i++) {
        char c1 = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            char c2 = word2.charAt(j);
            if (c1 == c2) {
                commonLetters.put(c1, commonLetters.getOrDefault(c1, 0) + 1);
            }
        }
    }

    // Calculate the approximate value
    int numCommon = commonLetters.values().stream().mapToInt(e -> e).sum();
    int denom = word1.length() + word2.length();
    double approx = (double)numCommon / (double)denom;

    // Reduce the fraction
    int gcd = getGCD(numCommon, denom);
    int num = numCommon / gcd;
    int den = denom / gcd;

    // Return the approximate value as a fraction
    return num + "/" + den;
}

