public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the index of the 5th percentile element
    int index5thPercentile = (int) (arr.length * 0.05);

    // Find the index of the 95th percentile element
    int index95thPercentile = (int) (arr.length - (arr.length * 0.05));

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = index5thPercentile; i < index95thPercentile; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    double mean = (double) sum / (index95thPercentile - index5thPercentile);

    // Check the error within 10^-5
    double error = Math.abs(mean - Math.round(mean * 100000) / 100000);
    if (error < 10E-5) {
        return mean;
    } else {
        return -1;
    }
}

