		return false;
	}

	// Check if all pairs are divisible by k
	for (Map.Entry<Integer, Integer> entry : pairs.entrySet()) {
		if (entry.getValue() % 2 == 0) {
			// If any pair is not divisible by k, return false
			return false;
		}
	}

	return true;
}

