public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // initialize the visitation status of all nodes as unvisited
    boolean[] visited = new boolean[n];
    for (int i = 0; i < n; i++) {
        visited[i] = false;
    }

    // create a min heap to store the nodes to visit and their distances from the starting node
    PriorityQueue<int[]> pq = new PriorityQueue<int[]>(Comparator.comparingInt(a -> a[1]));
    pq.add(new int[] {0, 0}); // start at node 0 with distance 0

    // loop until all nodes have been visited
    while (!pq.isEmpty()) {
        // extract the node with the minimum distance from the starting node
        int[] current = pq.poll();
        int node = current[0];
        int distance = current[1];

        // if the node has not been visited before and it has an apple, return the distance
        if (!visited[node] && hasApple[node]) {
            return distance;
        }

        // mark the node as visited
        visited[node] = true;

        // add the neighbors of the current node to the min heap if they have not been visited before
        for (int neighbor : edges[node]) {
            if (!visited[neighbor]) {
                pq.add(new int[] {neighbor, distance + 1});
            }
        }
    }

    // return 0 if all nodes have been visited
    return 0;
}

