        int smallest = -1;
        for (int i = 0; i < s.length(); i++) {
            if (!used[i] && (smallest == -1 || s.charAt(i) < s.charAt(smallest))) {
                smallest = i;
            }
        }
        result += s.charAt(smallest);
        used[smallest] = true;

        // Step 2
        int smallestGreater = -1;
        for (int i = 0; i < s.length(); i++) {
            if (!used[i] && s.charAt(i) > result.charAt(result.length() - 1) && (smallestGreater == -1 || s.charAt(i) < s.charAt(smallestGreater))) {
                smallestGreater = i;
            }
        }
        result += s.charAt(smallestGreater);
        used[smallestGreater] = true;

        // Step 3
        int largest = -1;
        for (int i = 0; i < s.length(); i++) {
            if (!used[i] && (largest == -1 || s.charAt(i) > s.charAt(largest))) {
                largest = i;
            }
        }
        result += s.charAt(largest);
        used[largest] = true;

        // Step 4
        int largestSmaller = -1;
        for (int i = 0; i < s.length(); i++) {
            if (!used[i] && s.charAt(i) < result.charAt(result.length() - 1) && (largestSmaller == -1 || s.charAt(i) > s.charAt(largestSmaller))) {
                largestSmaller = i;
            }
