public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> pq = new PriorityQueue<>();
    for (char c : s.toCharArray()) {
        pq.offer(c);
    }
    while (!pq.isEmpty()) {
        char c = pq.poll();
        result.append(c);
        while (pq.size() > 0 && pq.peek() > c) {
            c = pq.poll();
            result.append(c);
        }
        while (pq.size() > 0 && pq.peek() < c) {
            c = pq.poll();
            result.append(c);
        }
    }
    return result.toString();
}

