public static int uniqueMorseRepresentations(String[] words) {
  // Initialize a map to store the unique Morse code representations
  Map<String, Integer> morseMap = new HashMap<>();

  // Loop through each word in the input array
  for (String word : words) {
    // Split the word into individual letters
    String[] letters = word.split("");

    // Initialize a string buffer to store the Morse code of the word
    StringBuilder morseCode = new StringBuilder();

    // Loop through each letter in the word
    for (String letter : letters) {
      // Convert the letter to its Morse code
      String morse = toMorseCode(letter);

      // Add the Morse code to the string buffer
      morseCode.append(morse);
    }

    // Get the unique Morse code representation of the word
    String morseRepresentation = morseCode.toString();

    // If the Morse code representation is already in the map,
    // just increment the count of the existing entry
    if (morseMap.containsKey(morseRepresentation)) {
      morseMap.put(morseRepresentation, morseMap.get(morseRepresentation) + 1);
    }
    // Otherwise, add a new entry to the map
    else {
      morseMap.put(morseRepresentation, 1);
    }
  }

  // Return the size of the map, which is the number of unique Morse code representations
  return morseMap.size();
}

