    Map<Integer, Integer> fiboMap = new HashMap<>();
    fiboMap.put(0, -1);
    fiboMap.put(1, 0);
    int fiboIndex = 1;

    // Initialize variables to keep track of the sum and the minimum number of Fibonacci numbers
    int sum = 0;
    int minFiboCount = 0;

    // Loop through the Fibonacci numbers
    while (sum < k) {
        // Get the current Fibonacci number
        int fibo = fibonacci(fiboIndex);

        // Add the Fibonacci number to the sum
        sum += fibo;

        // If the sum is equal to k, return the minimum number of Fibonacci numbers
        if (sum == k) {
            minFiboCount = fiboIndex + 1;
            break;
