        // If the sum is greater than k, subtract the current Fibonacci number from the sum and add the index to the map
        if (sum > k) {
            sum -= fibo;
            fiboMap.put(fiboIndex, fiboMap.get(fiboIndex - 1) + 1);
        }

        // Increment the Fibonacci index
        fiboIndex++;
    }

    // Return the minimum number of Fibonacci numbers
    return minFiboCount;
}

