public int maxUniqueSplit(String s) {
    // Initialize an array to keep track of the number of times each letter appears
    int[] charCounts = new int[26];
    for (int i = 0; i < s.length(); i++) {
        charCounts[s.charAt(i) - 'a']++;
    }

    // Initialize a list to store the unique substrings
    List<String> substrings = new ArrayList<>();

    // Iterate through the string, starting from the first index
    for (int i = 0; i < s.length(); i++) {
        // Get the current character
        char currChar = s.charAt(i);

        // Check if the current character is already in the list of substrings
        if (!substrings.contains(String.valueOf(currChar))) {
            // If it's not, add it to the list of substrings
            substrings.add(String.valueOf(currChar));
        }

        // Iterate through the remaining characters in the string
        for (int j = i + 1; j < s.length(); j++) {
            // Get the next character
            char nextChar = s.charAt(j);

            // Check if the current character is the same as the next character
            if (currChar == nextChar) {
                // If they're the same, we can't form a unique substring with them
                break;
