            // Check if the current substring plus the next character is already in the list
            if (!substrings.contains(String.valueOf(currChar) + nextChar)) {
                // If it's not, add it to the list of substrings
                substrings.add(String.valueOf(currChar) + nextChar);
            }
        }
    }

    // Return the size of the list of substrings
    return substrings.size();
}

