public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        String number = Integer.toString(i);
        String previousDigit = number.substring(0, 1);
        int previousDigitInt = Integer.parseInt(previousDigit);
        for (int j = 1; j < number.length(); j++) {
            String currentDigit = number.substring(j, j + 1);
            int currentDigitInt = Integer.parseInt(currentDigit);
            if (previousDigitInt == currentDigitInt - 1 || previousDigitInt == currentDigitInt + 1) {
                steppingNumbers.add(i);
                break;
            }
            previousDigit = currentDigit;
        }
    }
    return steppingNumbers;
}

